index 18c9fbe2c..84217697f 100644
--- a/src/com/google/javascript/jscomp/InlineVariables.java
+++ b/src/com/google/javascript/jscomp/InlineVariables.java
@@ -182,6 +182,18 @@ class InlineVariables implements CompilerPass {
             Reference init = referenceInfo.getInitializingReference();
             Node value = init.getAssignedValue();
             if (value != null && value.getType() == Token.NAME) {
+              // If the aliased value is a parameter of the current function
+              // and the function modifies or escapes its "arguments" object,
+              // the parameter's value can be modified through arguments[i].
+              // In that case, replacing the alias with the parameter name
+              // would change semantics.
+              Var aliasedVar = t.getScope().getVar(value.getString());
+              if (aliasedVar != null
+                  && aliasedVar.scope == t.getScope()
+                  && isParameter(aliasedVar)
+                  && maybeEscapedOrModifiedArguments(t.getScope())) {
+                continue;
+              }
               aliasCandidates.put(value, new AliasCandidate(v, referenceInfo));
             }
           }
@@ -189,6 +201,61 @@ class InlineVariables implements CompilerPass {
       }
     }

+    /** @return true if v is a function parameter (its name is under an LP). */
+    private boolean isParameter(Var v) {
+      Node parent = v.getParentNode();
+      return parent != null && parent.getType() == Token.LP;
+    }
+
+    /**
+     * @return true if the function scope's body references "arguments" in any
+     *     way other than a read of {@code arguments[i]}. This is a
+     *     conservative approximation of whether the implicit binding between
+     *     positional parameters and the arguments object may have been broken.
+     */
+    private boolean maybeEscapedOrModifiedArguments(Scope scope) {
+      if (!scope.isLocal()) {
+        return false;
+      }
+      Node functionNode = scope.getRootNode();
+      Preconditions.checkState(functionNode.getType() == Token.FUNCTION);
+      return referencesArgumentsUnsafely(functionNode.getLastChild());
+    }
+
+    /**
+     * Walks the subtree rooted at n (excluding nested functions) looking for
+     * any reference to the "arguments" identifier that is NOT a simple read
+     * of {@code arguments[i]}.
+     */
+    private boolean referencesArgumentsUnsafely(Node n) {
+      if (n.getType() == Token.FUNCTION) {
+        return false;
+      }
+      if (n.getType() == Token.NAME
+          && "arguments".equals(n.getString())) {
+        Node parent = n.getParent();
+        // A read of arguments[i] is safe.
+        if (parent != null && parent.getType() == Token.GETELEM
+            && parent.getFirstChild() == n) {
+          Node grandparent = parent.getParent();
+          boolean isWriteTarget =
+              grandparent != null
+                  && NodeUtil.isAssignmentOp(grandparent)
+                  && grandparent.getFirstChild() == parent;
+          if (!isWriteTarget) {
+            return false;
+          }
+        }
+        return true;
+      }
+      for (Node c = n.getFirstChild(); c != null; c = c.getNext()) {
+        if (referencesArgumentsUnsafely(c)) {
+          return true;
+        }
+      }
+      return false;
+    }
+
